#include "cinema_codec.h"
uint16_t cinema_rd16(const uint8_t*p){return (uint16_t)p[0]|((uint16_t)p[1]<<8);} uint32_t cinema_rd32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);} void cinema_wr16(uint8_t*p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);} void cinema_wr32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);} uint32_t cinema_crc32_zeroed(const uint8_t*d,size_t n,size_t z,size_t l){uint32_t c=0xffffffffu;size_t i;for(i=0;i<n;i++){uint8_t b=(i>=z&&i-z<l)?0:d[i];unsigned k;c^=b;for(k=0;k<8;k++)c=(c>>1)^(0xedb88320u&(uint32_t)-(int32_t)(c&1u));}return ~c;}
